//! c-usagefu r9 items 4/5: ONE eligible-flow relation BY CALL IDENTITY, shared
//! by the rollup, both aggregates and the TPM windows, with cumulative
//! Session stock used only when no eligible flow exists.
//!
//! The tests upgrade an ACTUAL pre-r6 database (old schema created with rows,
//! THEN migrate — not migrate-empty-then-insert) and append NEW usage through
//! the public ingest path from observations a REAL CodexAdapter generated by
//! polling a rollout (the same channel production uses). Coverage:
//! - a Message never hides an unrelated Turn-only call (item 4);
//! - a Turn represented by a matching Message is counted once (item 4);
//! - Session-only cumulative history takes its LATEST stock, not its sum
//!   (item 5);
//! - stock-only totals switch to flow the moment a real call arrives, and
//!   legacy NULL-scope Turns count as flow (item 5).

use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};

use remuda_driver::adapters::{
    AdapterHome, AdapterObservation, CodexAdapter, FileSignalAdapter, StampCtx, stamp,
};
use remuda_hub::usage_store_test_support::{
    JournalRecord, RollupRequest, aggregate_instance, aggregate_supply, insert_usage_event,
    migrate, project_usage_event, rollup_instance,
};
use remuda_protocol::{HostId, Id, InstanceId, ObservationPayload, RunId};
use rusqlite::Connection;

const INSTANCE: &str = "ins_r9_item4";
const PROFILE: &str = "pvp_r9";
const MODEL: &str = "gpt-5.4";

/// A real pre-r6 schema: scope_id exists (c-ctxusage era) but turn_id does
/// not (r6 item 5 added it), and none of the r9 dedupe indexes exist.
const PRE_R6_SCHEMA: &str = "CREATE TABLE usage_events (
    instance_id TEXT NOT NULL,
    seq INTEGER NOT NULL,
    profile_id TEXT,
    model TEXT,
    scope TEXT NOT NULL,
    scope_id TEXT,
    mode TEXT NOT NULL,
    metric_revision INTEGER NOT NULL DEFAULT 1,
    total_tokens INTEGER,
    input_tokens INTEGER,
    output_tokens INTEGER,
    cache_read_tokens INTEGER,
    cache_write_tokens INTEGER,
    cost_usd TEXT,
    accounting TEXT NOT NULL DEFAULT 'estimated',
    observed_at TEXT NOT NULL,
    observed_at_source TEXT NOT NULL DEFAULT 'ingest',
    native_context_window INTEGER,
    PRIMARY KEY (instance_id, seq)
);";

fn rfc(seconds_ago: i64) -> String {
    let t = time::OffsetDateTime::now_utc() - time::Duration::seconds(seconds_ago);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",
        t.year(),
        t.month() as u8,
        t.day(),
        t.hour(),
        t.minute(),
        t.second(),
        t.millisecond()
    )
}

/// Lay a real 0.154-shaped rollout holding `turns` token_usage_records
/// (turn id, response id, input/output/cache at the shared timestamp) and
/// poll it through the real CodexAdapter.
fn run_real_codex_adapter(
    dir: &Path,
    session_id: &str,
    turns: &[(&str, &str, i64, i64, i64, i64)],
) -> Vec<AdapterObservation> {
    let home = dir.join("codex-home");
    let session_dir = home.join("sessions/2026/10/12");
    std::fs::create_dir_all(&session_dir).unwrap();
    let mut body = String::new();
    let meta_at = rfc(3);
    body.push_str(
        &serde_json::json!({
            "timestamp": meta_at,
            "ordinal": 0,
            "type": "session_meta",
            "payload": {"id": session_id, "session_id": session_id,
                        "cwd": dir.display().to_string(), "timestamp": meta_at},
        })
        .to_string(),
    );
    body.push('\n');
    body.push_str(
        &serde_json::json!({
            "timestamp": meta_at,
            "ordinal": 1,
            "type": "response_item",
            "payload": {
                "type": "message", "id": "m_env", "role": "user",
                "content": [{"type": "input_text",
                             "text": "<environment_context>"}],
                "internal_chat_message_metadata_passthrough": {
                    "content_item_kinds": ["environments.environment_context"]
                }
            }
        })
        .to_string(),
    );
    body.push('\n');
    body.push_str(
        &serde_json::json!({
            "timestamp": meta_at,
            "ordinal": 2,
            "type": "response_item",
            "payload": {
                "type": "message", "id": "m_u", "role": "user",
                "content": [{"type": "input_text", "text": "go"}],
                "internal_chat_message_metadata_passthrough": {
                    "content_item_kinds": ["user.text"]
                }
            }
        })
        .to_string(),
    );
    body.push('\n');
    let mut ordinal = 3u32;
    for (index, (turn_id, response_id, input, cached, out, _total)) in turns.iter().enumerate() {
        let at = rfc(1 + index as i64);
        body.push_str(
            &serde_json::json!({
                "timestamp": at, "ordinal": ordinal, "type": "event_msg",
                "payload": {"type": "task_started", "turn_id": turn_id},
            })
            .to_string(),
        );
        body.push('\n');
        ordinal += 1;
        let total = input + cached + out;
        body.push_str(
            &serde_json::json!({
                "timestamp": at, "ordinal": ordinal, "type": "token_usage_record",
                "payload": {
                    "turn_id": turn_id,
                    "response_id": response_id,
                    "usage": {
                        "input_tokens": input,
                        "cached_input_tokens": cached,
                        "cache_creation_input_tokens": 0,
                        "output_tokens": out,
                        "reasoning_output_tokens": 0,
                        "total_tokens": total,
                    }
                }
            })
            .to_string(),
        );
        body.push('\n');
        ordinal += 1;
        body.push_str(
            &serde_json::json!({
                "timestamp": at, "ordinal": ordinal, "type": "event_msg",
                "payload": {"type": "task_complete", "turn_id": turn_id},
            })
            .to_string(),
        );
        body.push('\n');
        ordinal += 1;
    }
    std::fs::write(
        session_dir.join(format!("rollout-{session_id}.jsonl")),
        body,
    )
    .unwrap();
    std::fs::write(
        home.join("session_index.jsonl"),
        format!("{{\"id\":\"{session_id}\"}}\n"),
    )
    .unwrap();

    let mut adapter = CodexAdapter::new(AdapterHome {
        home,
        cwd: dir.to_path_buf(),
        pid: None,
        launched_at: None,
        resume_session_id: None,
    })
    .with_fallback_model(MODEL);
    let mut all = Vec::new();
    for _ in 0..6 {
        let observed = adapter.poll().expect("codex poll");
        if observed.is_empty() && !all.is_empty() {
            break;
        }
        all.extend(observed);
    }
    all
}

/// Project + persist every adapter Usage observation through the public
/// journal ingest path, starting at `next_seq`.
fn ingest(conn: &Connection, observed: &[AdapterObservation], next_seq: &AtomicU64) {
    let stamp_ctx = StampCtx {
        instance_id: InstanceId::new(),
        host_id: HostId::new(),
        journal_id: Id::new("obj").unwrap(),
        run_id: RunId::new(),
        session_id: "codex-r9".into(),
    };
    for obs in observed {
        if !matches!(obs.payload, ObservationPayload::Usage(_)) {
            continue;
        }
        let number = next_seq.fetch_add(1, Ordering::SeqCst) + 1;
        let stamped = stamp(&stamp_ctx, number, obs).expect("stamp usage observation");
        let event = serde_json::to_value(&stamped).expect("serialize");
        let record = JournalRecord {
            instance_id: INSTANCE.into(),
            seq: number as i64,
            event_id: stamped.event_id.as_id().as_str().to_owned(),
            event,
            observed_at: rfc(0),
        };
        let row = project_usage_event(&record, Some(PROFILE), Some(MODEL)).expect("project");
        insert_usage_event(conn, &row).expect("insert");
    }
}

/// Sum of the projected Message rows' cost (the adapter priced them from the
/// real pricing table with `MODEL` as fallback).
fn message_cost(conn: &Connection) -> f64 {
    conn.query_row(
        "SELECT COALESCE(SUM(CAST(cost_usd AS REAL)), 0.0) FROM usage_events
         WHERE instance_id = ?1 AND scope = 'message'",
        [INSTANCE],
        |row| row.get(0),
    )
    .unwrap()
}

#[test]
fn an_unmatched_turn_only_call_and_a_message_call_sum_to_120() {
    // Native Turn t1 = 100 out (pre-r6 history) + a real adapter Message t2
    // = 20 out. Per-instance gating hid t1; per-call eligibility keeps it.
    let dir = tempfile::tempdir().unwrap();
    let conn = Connection::open_in_memory().unwrap();
    conn.execute_batch(PRE_R6_SCHEMA).unwrap();
    conn.execute(
        "INSERT INTO usage_events
            (instance_id, seq, profile_id, model, scope, scope_id, mode,
             input_tokens, output_tokens, cache_read_tokens, cost_usd,
             observed_at, observed_at_source)
         VALUES (?1, 1, ?2, ?3, 'turn', 't1', 'snapshot',
                 100, 100, 900, '0.10', ?4, 'native')",
        rusqlite::params![INSTANCE, PROFILE, MODEL, rfc(2)],
    )
    .unwrap();
    migrate(&conn).unwrap();
    // turn_id was added by the migration; the old turn stays unmatched.
    let turn_id_null: Option<String> = conn
        .query_row(
            "SELECT turn_id FROM usage_events WHERE scope='turn'",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert!(turn_id_null.is_none(), "the pre-r6 turn has no turn_id");

    // A NEW call t2 arrives through the real codex adapter. Codex's raw
    // input_tokens INCLUDES cached tokens (50 cached, 0 fresh -> 50).
    let observed = run_real_codex_adapter(
        dir.path(),
        "r9-item4-session",
        &[("t2", "r2", 50, 50, 20, 70)],
    );
    assert!(
        observed
            .iter()
            .any(|o| matches!(&o.payload, ObservationPayload::Usage(u) if u.scope == remuda_protocol::UsageScope::Message)),
        "the real adapter emitted a Message usage observation"
    );
    let next_seq = AtomicU64::new(1);
    ingest(&conn, &observed, &next_seq);

    let rollup = rollup_instance(
        &conn,
        &RollupRequest {
            instance_id: INSTANCE,
            kind: "codex",
            spec_model: Some(MODEL),
            effective_model: None,
            profile_id: Some(PROFILE),
        },
    )
    .unwrap()
    .unwrap();
    assert_eq!(rollup.turns, 2, "t1 Turn and t2 Message are distinct calls");
    assert_eq!(rollup.session_output_tokens, Some(120), "100 + 20, not 20");
    assert_eq!(rollup.session_input_tokens, Some(100));
    assert_eq!(rollup.cache_read_tokens, Some(950), "900 + 50");
    assert_eq!(rollup.tpm_out_60s, Some(120));
    assert_eq!(rollup.tpm_in_60s, Some(100));
    assert_eq!(rollup.tpm_out_5m, Some(24), "120 / 5 minutes");
    assert_eq!(rollup.tpm_in_5m, Some(20));

    let instance = aggregate_instance(&conn, INSTANCE).unwrap();
    assert_eq!(
        instance.output_tokens,
        Some(120),
        "aggregate keeps the Turn call"
    );
    assert_eq!(instance.input_tokens, Some(100));
    // c-usagefu r10 item 6 (Ruling B): eligible flow EXISTS (the old Turn t1
    // plus the new Message), so COST follows the flow and the priced Session
    // stock is ignored: bill = the unmatched historical Turn's 0.10 + the new
    // Message's own priced cost.
    let expected_cost = 0.10 + message_cost(&conn);
    let supply = aggregate_supply(&conn, PROFILE, MODEL).unwrap();
    assert!(
        (instance.cost_usd.unwrap() - expected_cost).abs() < 1e-9,
        "flow cost 0.10 + message, not the priced stock, got {}",
        instance.cost_usd.unwrap()
    );
    assert_eq!(supply.output_tokens, Some(120));
    assert!((supply.cost_usd.unwrap() - expected_cost).abs() < 1e-9);
}

#[test]
fn a_turn_represented_by_a_matching_message_is_counted_once_after_upgrade() {
    // Byte-0 replay across the r6 boundary: the pre-r6 Turn t1 = 100 out is
    // the same call as the real adapter's Message r1 (turn_id t1). The
    // migrated Turn must be dropped; the new t2 Message still counts.
    let dir = tempfile::tempdir().unwrap();
    let conn = Connection::open_in_memory().unwrap();
    conn.execute_batch(PRE_R6_SCHEMA).unwrap();
    conn.execute(
        "INSERT INTO usage_events
            (instance_id, seq, profile_id, model, scope, scope_id, mode,
             input_tokens, output_tokens, cache_read_tokens, cost_usd,
             observed_at, observed_at_source)
         VALUES (?1, 1, ?2, ?3, 'turn', 't1', 'snapshot',
                 100, 100, 900, '0.10', ?4, 'native')",
        rusqlite::params![INSTANCE, PROFILE, MODEL, rfc(2)],
    )
    .unwrap();
    migrate(&conn).unwrap();

    // The real adapter replays BOTH calls: r1 is t1 (same call as the old
    // Turn), r2 is a new t2.
    let observed = run_real_codex_adapter(
        dir.path(),
        "r9-item4-dual-session",
        &[
            ("t1", "r1", 1000, 900, 100, 1100),
            ("t2", "r2", 50, 50, 20, 70),
        ],
    );
    let next_seq = AtomicU64::new(1);
    ingest(&conn, &observed, &next_seq);

    let rollup = rollup_instance(
        &conn,
        &RollupRequest {
            instance_id: INSTANCE,
            kind: "codex",
            spec_model: Some(MODEL),
            effective_model: None,
            profile_id: Some(PROFILE),
        },
    )
    .unwrap()
    .unwrap();
    assert_eq!(rollup.turns, 2);
    assert_eq!(
        rollup.session_output_tokens,
        Some(120),
        "t1 counted once via its Message, plus t2's 20"
    );
    assert_eq!(rollup.session_input_tokens, Some(100));
    assert_eq!(rollup.cache_read_tokens, Some(950), "900 + 50, not 1850");
    assert_eq!(rollup.tpm_out_60s, Some(120));
    assert_eq!(rollup.tpm_in_5m, Some(20));

    // Cost: the old Turn's 0.10 is suppressed by the matching Message; the
    // bill is the adapter-priced Message stream only.
    let expected_cost = message_cost(&conn);
    let instance = aggregate_instance(&conn, INSTANCE).unwrap();
    assert_eq!(
        instance.output_tokens,
        Some(120),
        "not 220 (100 turn + 100 + 20)"
    );
    assert!(
        (instance.cost_usd.unwrap() - expected_cost).abs() < 1e-9,
        "no +0.10"
    );
    let supply = aggregate_supply(&conn, PROFILE, MODEL).unwrap();
    assert_eq!(supply.output_tokens, Some(120));
    assert!((supply.cost_usd.unwrap() - expected_cost).abs() < 1e-9);
}

/// Insert an old-shape cumulative Session growth point into the pre-r6
/// table (NULL turn_id column did not exist then).
fn old_session_row(
    conn: &Connection,
    seq: i64,
    scope_id: Option<&str>,
    input: i64,
    out: i64,
    cost: &str,
    at: &str,
) {
    conn.execute(
        "INSERT INTO usage_events
            (instance_id, seq, profile_id, model, scope, scope_id, mode,
             input_tokens, output_tokens, cost_usd, accounting,
             observed_at, observed_at_source)
         VALUES (?1, ?2, ?3, ?4, 'session', ?5, 'snapshot',
                 ?6, ?7, ?8, 'estimated', ?9, 'native')",
        rusqlite::params![
            INSTANCE, seq, PROFILE, MODEL, scope_id, input, out, cost, at
        ],
    )
    .unwrap();
}

#[test]
fn session_only_cumulative_history_takes_the_latest_stock_not_the_sum() {
    // r9 item 5: a pre-r6 session-only instance (stock-only Grok/old-codex
    // shape) grew 10 then 30. Totals are the LATEST cumulative stock (30),
    // never 40 — on the rollup AND both aggregates. Rates remain the
    // timestamped increment (20).
    let conn = Connection::open_in_memory().unwrap();
    conn.execute_batch(PRE_R6_SCHEMA).unwrap();
    old_session_row(&conn, 1, Some("s1"), 10, 5, "0.01", &rfc(40));
    old_session_row(&conn, 2, Some("s1"), 30, 15, "0.03", &rfc(2));
    migrate(&conn).unwrap();

    let rollup = rollup_instance(
        &conn,
        &RollupRequest {
            instance_id: INSTANCE,
            kind: "grok",
            spec_model: Some(MODEL),
            effective_model: None,
            profile_id: Some(PROFILE),
        },
    )
    .unwrap()
    .unwrap();
    assert_eq!(
        rollup.session_input_tokens,
        Some(30),
        "latest stock, not 40"
    );
    assert_eq!(rollup.session_output_tokens, Some(15));
    assert_eq!(rollup.tpm_in_60s, Some(20), "30 - 10 increment in window");
    assert_eq!(rollup.tpm_out_60s, Some(10));
    assert_eq!(rollup.tpm_in_5m, Some(4));
    assert_eq!(rollup.tpm_out_5m, Some(2));

    let instance = aggregate_instance(&conn, INSTANCE).unwrap();
    assert_eq!(
        instance.input_tokens,
        Some(30),
        "aggregate latest, not 10+30"
    );
    assert_eq!(instance.output_tokens, Some(15));
    assert!(
        (instance.cost_usd.unwrap() - 0.03).abs() < 1e-9,
        "latest stock cost"
    );
    let supply = aggregate_supply(&conn, PROFILE, MODEL).unwrap();
    assert_eq!(supply.input_tokens, Some(30));
    assert_eq!(supply.output_tokens, Some(15));
    assert!((supply.cost_usd.unwrap() - 0.03).abs() < 1e-9);

    // Idempotent re-migrate keeps the latest-stock answer.
    migrate(&conn).unwrap();
    assert_eq!(
        aggregate_instance(&conn, INSTANCE).unwrap().input_tokens,
        Some(30)
    );
}

#[test]
fn stock_only_instance_switches_to_flow_once_a_real_call_arrives() {
    // r9 item 5 mixed scope: pre-r6 cumulative stock 10 -> 30, then the
    // upgraded instance emits a REAL Message call (7 out). Eligible flow now
    // exists, so totals are the flow ALONE — never stock + flow and never the
    // larger stock fallback.
    let dir = tempfile::tempdir().unwrap();
    let conn = Connection::open_in_memory().unwrap();
    conn.execute_batch(PRE_R6_SCHEMA).unwrap();
    old_session_row(&conn, 1, Some("s1"), 10, 5, "0.01", &rfc(40));
    old_session_row(&conn, 2, Some("s1"), 30, 15, "0.03", &rfc(20));
    migrate(&conn).unwrap();

    let observed = run_real_codex_adapter(
        dir.path(),
        "r9-item5-flow-session",
        &[("t3", "r3", 5, 0, 7, 12)],
    );
    ingest(&conn, &observed, &AtomicU64::new(2));

    let rollup = rollup_instance(
        &conn,
        &RollupRequest {
            instance_id: INSTANCE,
            kind: "codex",
            spec_model: Some(MODEL),
            effective_model: None,
            profile_id: Some(PROFILE),
        },
    )
    .unwrap()
    .unwrap();
    assert_eq!(rollup.turns, 1);
    assert_eq!(rollup.session_output_tokens, Some(7), "flow only, not 15+7");
    assert_eq!(rollup.session_input_tokens, Some(5), "flow only, not 30+5");
    assert_eq!(rollup.tpm_out_60s, Some(7));

    let instance = aggregate_instance(&conn, INSTANCE).unwrap();
    assert_eq!(
        instance.output_tokens,
        Some(7),
        "no cumulative history on flow"
    );
    assert_eq!(instance.input_tokens, Some(5));
    let supply = aggregate_supply(&conn, PROFILE, MODEL).unwrap();
    assert_eq!(supply.output_tokens, Some(7));
    assert_eq!(supply.input_tokens, Some(5));
}

#[test]
fn a_legacy_null_scope_turn_counts_as_flow_against_cumulative_stock() {
    // r9 item 5 legacy mixed scope: pre-scopeId NULL-scope Session chain
    // (10 -> 30) plus a legacy NULL-scope Turn row. Legacy Turns ARE eligible
    // flow, so the stock must not be used: totals are the Turn's counters on
    // the rollup and both aggregates (native time feeds the rate window).
    let conn = Connection::open_in_memory().unwrap();
    conn.execute_batch(PRE_R6_SCHEMA).unwrap();
    conn.execute(
        "INSERT INTO usage_events
            (instance_id, seq, profile_id, model, scope, scope_id, mode,
             input_tokens, output_tokens, cost_usd, accounting,
             observed_at, observed_at_source)
         VALUES (?1, 1, ?2, ?3, 'session', NULL, 'snapshot',
                 10, 5, '0.01', 'estimated', ?4, 'native'),
                (?1, 2, ?2, ?3, 'session', NULL, 'snapshot',
                 30, 15, '0.03', 'estimated', ?5, 'native'),
                (?1, 3, ?2, ?3, 'turn', NULL, 'snapshot',
                 40, 20, '0.04', 'estimated', ?6, 'native')",
        rusqlite::params![INSTANCE, PROFILE, MODEL, rfc(40), rfc(20), rfc(2)],
    )
    .unwrap();
    migrate(&conn).unwrap();

    let rollup = rollup_instance(
        &conn,
        &RollupRequest {
            instance_id: INSTANCE,
            kind: "codex",
            spec_model: Some(MODEL),
            effective_model: None,
            profile_id: Some(PROFILE),
        },
    )
    .unwrap()
    .unwrap();
    assert_eq!(rollup.turns, 1);
    assert_eq!(rollup.session_input_tokens, Some(40), "legacy Turn flow");
    assert_eq!(rollup.session_output_tokens, Some(20));
    assert_eq!(rollup.tpm_in_60s, Some(40), "native legacy Turn rates");
    assert_eq!(rollup.tpm_out_60s, Some(20));

    let instance = aggregate_instance(&conn, INSTANCE).unwrap();
    assert_eq!(instance.input_tokens, Some(40), "not 30 stock, not 30+40");
    assert_eq!(instance.output_tokens, Some(20));
    let supply = aggregate_supply(&conn, PROFILE, MODEL).unwrap();
    assert_eq!(supply.input_tokens, Some(40));
    assert_eq!(supply.output_tokens, Some(20));
}
